{
	m_maxVel.x = -40.0f;
	m_maxVel.y = 0.0f;
	m_slowDownThreshold = 80;
	m_slowDownRatio = 0.67f;
	m_speedUpRatio = 2.0f - m_slowDownRatio;
}

// FUNCTION: BFME2 0x005C50A8 size=106 name=?initReverseAnimateWindow@ProcessAnimateWindowSlideFromRight@@UAEXPAVAnimateWindow@@I@Z evidence=N:ledger
void ProcessAnimateWindowSlideFromRight::initReverseAnimateWindow(AnimateWindow *animWin, unsigned int maxDelay)
{
	if (!animWin)
		return;

	if (animWin->getDelay() > 0)
		animWin->setStartTime(timeGetTime() + (maxDelay - animWin->getDelay()));

	// Run the slide back the way it came.
	Coord2D vel = animWin->getVel();
	vel.x *= -1.0f;
	vel.y *= -1.0f;
	animWin->setVel(vel);
	animWin->setFinished(false);
}

// FUNCTION: BFME2 0x005C5112 size=211 name=?initAnimateWindow@ProcessAnimateWindowSlideFromRight@@UAEXPAVAnimateWindow@@@Z evidence=N:ledger
void ProcessAnimateWindowSlideFromRight::initAnimateWindow(AnimateWindow *animWin)
{
	ICoord2D restPos = {0,0};
	ICoord2D startPos = {0,0};
	ICoord2D curPos = {0,0};
	ICoord2D endPos = {0,0};
	Coord2D vel(0.0f, 0.0f);

	if(!animWin)
	{
		return;
	}
	animWin->setFinished( false );

	// it's set that the window is passed in as it's current position being it's rest position
	// so save off the rest position
	GameWindow *win = animWin->getGameWindow();
	if(!win)
	{
		return;
	}
	win->winGetPosition(&restPos.x, &restPos.y);
	endPos.x = restPos.x;
	endPos.y = restPos.y;

	//set the initial positions for the window. In this case, off the Right of the screen
	Int travelDistance = TheDisplay->getWidth();// / 4 * 3;
	startPos.x = curPos.x = restPos.x + travelDistance;
	startPos.y = curPos.y = restPos.y;

	//set the window's position to the new start positions.
	win->winSetPosition(startPos.x, startPos.y);

	//Now initialize the velocities
	vel.x = m_maxVel.x;
	vel.y = 0.0f;

	animWin->setAnimData(startPos, endPos, curPos, restPos, vel, timeGetTime() + animWin->getDelay(), 0);
}

// FUNCTION: BFME2 0x005C51E5 size=233 name=?reverseAnimateWindow@ProcessAnimateWindowSlideFromRight@@UAE_NPAVAnimateWindow@@@Z evidence=N:ledger
bool ProcessAnimateWindowSlideFromRight::reverseAnimateWindow(AnimateWindow *animWin)
{
	if (!animWin)
		return true;
	if (animWin->isFinished())
		return true;
	if (timeGetTime() < animWin->getStartTime())
		return false;

	GameWindow *win = animWin->getGameWindow();
	if (!win)
		return true;

	// Slide back toward the start position, speeding up once past the
	// slow-down distance from the end.
	ICoord2D curPos = animWin->getCurPos();
	ICoord2D startPos = animWin->getStartPos();
	Coord2D vel = animWin->getVel();
	curPos.x += (Int)vel.x;
	if (curPos.x > startPos.x)
	{
		animWin->setFinished(true);
		win->winSetPosition(startPos.x, curPos.y);
		return true;
	}
	win->winSetPosition(curPos.x, curPos.y);
	animWin->setCurPos(curPos);

	ICoord2D endPos = animWin->getEndPos();
	Real speed;
	if (curPos.x - endPos.x <= m_slowDownThreshold)
		speed = vel.x * m_speedUpRatio;
	else
		speed = -m_maxVel.x;
	if (speed > -m_maxVel.x)
		speed = -m_maxVel.x;
	Coord2D newVel;
	newVel.x = speed;
	newVel.y = vel.y;
	animWin->setVel(newVel);
	return false;
}

